struct port_acquire_args
{
    apr_pool_t* pool;
    server_rec* vhost;
    h3_server_conf* conf;
};

#ifdef __linux__
/* The parent binds the QUIC sockets while still privileged and keeps them across restarts.
 * One SO_REUSEPORT socket per httpd listener bucket (ListenCoresBucketsRatio), so the kernel hash stays stable when children come and go. */
typedef struct
{
    apr_pool_t* pool;
    int* fds;
    int n;
    apr_port_t port;
    int routed; /* an eBPF program routes the packets by connection ID */
} h3_parent_socket;

/* The same count as httpd for ListenCoresBucketsRatio: online cores / ratio. Some MPMs count their buckets after post_config.
 * ponytail: top-level directive only, not one inside <IfModule>. */
static int listen_buckets(void)
{
#ifdef H3Q_BACKEND_OSSL
    /* Routing by connection ID needs ngtcp2 to put the bucket in the connection IDs. */
    return 1;
#endif
    for (ap_directive_t* d = ap_conftree; d; d = d->next)
    {
        if (ap_have_so_reuseport > 0 && !ap_cstr_casecmp(d->directive, "ListenCoresBucketsRatio"))
        {
            long ratio = atol(d->args);
            long n = ratio > 0 ? sysconf(_SC_NPROCESSORS_ONLN) / ratio : 1;
            int limit = 1;
            ap_mpm_query(AP_MPMQ_HARD_LIMIT_DAEMONS, &limit); /* A bucket with no child loses its peers. */
            return n < 1 ? 1 : n > limit ? limit : (int)n;
        }
    }
    return 1;
}

static h3_parent_socket* parent_socket(server_rec* s)
{
    void* ps = NULL;
    apr_pool_userdata_get(&ps, "mod_http3.parent_socket", s->process->pool);
    return ps;
}

/* The children inherit them; the child that binds the abstract name of a bucket owns its socket, and exit releases it. */
static int owner_lock = -1;
static int child_bucket = -1;

static int own_port(apr_port_t port, int bucket)
