    cache->pool = pool;
    cache->capacity = capacity;
    cache->table_size = table_size;
    cache->window = window;
    cache->full_policy = full_policy;
    cache->order_head = H3_REPLAY_INDEX_NONE;
    cache->order_tail = H3_REPLAY_INDEX_NONE;
    cache->free_head = 0;
    cache->stats.capacity = capacity;

